  StageGroup_120951_Desc = {
    Text = "Phía bên kia chiều không gian, quê hương xa cách lâu ngày phát ra tiếng gọi yếu ớt. \n Ý thức của thần linh lại một lần nữa hướng về cái nhìn hủy diệt, chặn lại nó, đánh bại nó, vượt qua không gian và thời gian xa xôi, lại đứng trước mặt nhau. \n Lời hứa, trong hành trình dài và tối tăm này, nó sẽ là điểm sáng duy nhất dẫn lối cho chúng ta."
  },
