  StageGroup_125684_Desc = {
    Text = "Kẽo kẹt— kẽo kẹt— nữ thần số mệnh quay chiếc xa quay của mình.\nKẽo kẹt— kẽo kẹt— sợi tơ định mệnh hội tụ trong tay nàng.\nNhững con rối xếp hàng bước vào, đặt chân lên tấm lưới vận mệnh.\nChúng nhảy múa. Chúng ca hát. Kẽo kẹt— kẽo kẹt—\nChúng cùng tấm lưới chết đi, lặng lẽ không một tiếng động."
