  StageGroup_130895_Desc = {
    Text = "Tham lam ban tặng nhiều hơn, dễ dàng thỏa mãn, sẽ lấy đi tất cả những gì mà nó đã có. \n Khi chúng ta nhìn về biển cả, cái mà chúng ta nhìn không chỉ là sự rộng lớn và vẻ đẹp của Ngài, biển cả nuốt chửng ký ức, biển cả nuốt chửng nỗi sợ hãi, tất cả những gì hội tụ của dòng chảy đều thoáng chốc biến mất. \n Biển cả đang gọi bạn, chìm vào sự im lặng cô đơn vĩnh cửu."
