  StageGroup_145355_Name = {
    Text = "Gương Vô Nhân"
  },
  StageGroup_145355_TypeText = {
    Text = "Cuộc Tranh Đoạt Tàn Sát"
  },
  StageGroup_145356_Desc = {
    Text = "Một vạn hai nghìn năm chờ đợi, Leviathan đã sớm chán ngán.\nCác vị vương đăng quang dưới chân Ngài, các thánh nhân trở nên tham lam trước mặt Ngài, các anh hùng thản nhiên tắm mình trong quyền vọng vô tận của Ngài. Vương miện đẫm máu rơi xuống, từ đầu người này sang đầu người khác.\nNgài nhai những màn kịch na ná nhau đó, như nuốt chửng những hạt bụi vô vị trong dải ngân hà. Ngài tưởng rằng, đó là tất cả những gì Ngài sẽ thấy trong sinh lực vĩnh hằng của mình.\nCho đến khi cô ấy xuất hiện trước mặt Ngài."
  },
  StageGroup_145356_Name = {
    Text = "Cho Đến Khi Kình Thiên Vẫn Lạc"
  },
  StageGroup_145356_TypeText = {
    Text = "duy thức tiềm hành"
  },
  StageGroup_145357_Name = {
    Text = "Mãnh Thú Bị Vây"
  },
  StageGroup_145357_TypeText = {
    Text = "Cuộc Tranh Đoạt Tàn Sát"
  },
  StageGroup_145358_Name = {
    Text = "Điện Đường Sát Thương"
  },
  StageGroup_145358_TypeText = {
    Text = "Cuộc Tranh Đoạt Tàn Sát"
  },
  StageGroup_145359_Name = {
    Text = "Vương Miện Quyền Vọng"
  },
  StageGroup_145359_TypeText = {
    Text = "Cuộc Tranh Đoạt Tàn Sát"
  },
  StageGroup_145360_Name = {
    Text = "Triều Cống"
  },
  StageGroup_145360_TypeText = {
    Text = "Cuộc Tranh Đoạt Tàn Sát"
  },
  StageGroup_146256_Desc = {
    Text = "Những dãy núi sừng sững tại tận cùng thế giới.\nTrên lớp băng tuyết trải dài đóng băng quanh năm, cơn đói khát cổ xưa đang thức tỉnh sau giấc ngủ dài.\nNúi há miệng rộng như vực thẳm, nở nụ cười trầm thấp đầy chế nhạo.\nHãy kiên nhẫn chờ đợi đi — những kẻ cầu nguyện đã trên đường tới bữa tiệc."
  },
  StageGroup_146256_Name = {
    Text = "Đại Tiệc Trên Núi Tuyết"
  },
  StageGroup_146256_TypeText = {
    Text = "Điều tra Khó khăn"
  },
  StageGroup_146257_Desc = {
    Text = "Những dãy núi sừng sững tại tận cùng thế giới.\nTrên lớp băng tuyết trải dài đóng băng quanh năm, cơn đói khát cổ xưa đang thức tỉnh sau giấc ngủ dài.\nNúi há miệng rộng như vực thẳm, nở nụ cười trầm thấp đầy chế nhạo.\nHãy kiên nhẫn chờ đợi đi — những kẻ cầu nguyện đã trên đường tới bữa tiệc."
  },
  StageGroup_146257_Name = {
    Text = "Đại Tiệc Trên Núi Tuyết"
  },
  StageGroup_146257_TypeText = {
    Text = "Điều tra"
  },
  StageGroup_146787_Desc = {
    Text = "Các thế hệ đã qua, chẳng ai nhớ đến, các thế hệ mai sau, người đời sau cũng chẳng nhớ đến.\nSự chấp nhặt vào những gì đã mất chẳng khác nào bắt gió, vì vậy ta ghét bỏ sinh mệnh này."
