  },
  StageGroup_15868_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  StageGroup_15868_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15868_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15869_Desc = {
    Text = "Chúng vặn vẹo, hòa quyện trong bóng tối, rồi được cẩn thận bảo quản trong tượng. \nĐây là một cuộc hội ngộ đã được dự mưu từ lâu."
  },
  StageGroup_15869_Name = {
    Text = "Hành trình Siêu việt"
  },
  StageGroup_15869_TypeText = {
    Text = "Hành trình Siêu việt"
  },
  StageGroup_15870_Desc = {
    Text = "Chúng vặn vẹo, hòa quyện trong bóng tối, rồi được cẩn thận bảo quản trong tượng. \nĐây là một cuộc hội ngộ đã được dự mưu từ lâu."
  },
  StageGroup_15870_Name = {
    Text = "Hành trình Siêu việt"
  },
  StageGroup_15870_TypeText = {
    Text = "Hành trình Siêu việt"
  },
  StageGroup_15871_Desc = {
    Text = "Chúng vặn vẹo, hòa quyện trong bóng tối, rồi được cẩn thận bảo quản trong tượng. \nĐây là một cuộc hội ngộ đã được dự mưu từ lâu."
  },
  StageGroup_15871_Name = {
    Text = "Hành trình Siêu việt"
  },
  StageGroup_15871_TypeText = {
    Text = "Hành trình Siêu việt"
  },
  StageGroup_15872_Desc = {
    Text = "Chúng giống như những phù thủy khó đoán, lang thang giữa các kẽ hở thời gian và không gian. \n Không có thù hận, không có sợ hãi, cũng không có lòng thương xót."
  },
  StageGroup_15872_Name = {
    Text = "Dư ảnh chiều"
  },
  StageGroup_15872_StageGroupRewardDescription = {
    Text = "<Black:vật liệu thăng cấp>"
  },
  StageGroup_15872_TypeText = {
    Text = "Dư ảnh chiều"
  },
  StageGroup_15873_Desc = {
    Text = "Lentiennam nổi tiếng với nền văn minh công nghiệp rực rỡ và lớp sương mù màu chì xám bao phủ thành phố. \nSương mù hiện diện khắp nơi, đối với người đi đường, nó giống như một sự bất tiện ngẫu nhiên và không đáng kể."
  },
  StageGroup_15873_Name = {
    Text = "Thành phố Sương Quái Dị"
  },
  StageGroup_15873_StageGroupRewardDescription = {
    Text = "<Black:bí ẩn>"
  },
  StageGroup_15873_TypeText = {
    Text = "Thành phố Sương Quái Dị"
  },
  StageGroup_15874_Desc = {
    Text = "Chúng vặn vẹo, hòa quyện trong bóng tối, rồi được cẩn thận bảo quản trong tượng. \nĐây là một cuộc hội ngộ đã được dự mưu từ lâu."
  },
  StageGroup_15874_Name = {
    Text = "Lãnh vực Hỗn loạn"
  },
  StageGroup_15874_TypeText = {
    Text = "Lãnh vực Hỗn loạn"
  },
  StageGroup_15875_Desc = {
    Text = "Mỗi đêm mưa rơi đều đi kèm với ý định giết người. \nLần này bạn sẽ đến thị trấn Renni phía bắc của thị trấn Rai, để điều tra một vụ án kỳ lạ…"
  },
  StageGroup_15875_Name = {
    Text = "Bóng tối của thị trấn mưa"
  },
  StageGroup_15875_TypeText = {
    Text = "Bản ghi đặc nhiệm"
  },
  StageGroup_15876_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
  StageGroup_15876_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15876_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15877_Desc = {
    Text = "\"Mỗi chìa khóa đều có một con số độc nhất, và cũng chỉ thuộc về một điều tra viên duy nhất.\" \n\"Điều đó cũng đồng nghĩa rằng, thời khắc chìa khóa rơi xuống cũng đánh dấu cái chết của điều tra viên sở hữu nó.\" \n\"Điều này tuyệt vời làm sao, vì ngay cả cái chết cũng là độc nhất vô nhị.\""
  },
  StageGroup_15877_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15877_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15878_Desc = {
    Text = "Di chuyển, chảy tràn... những bong bóng chất nguyên sinh đang lọt qua khe hở của xiềng xích. \nĐây là cái giá mà cô phải trả cho \"tự do\"."
  },
  StageGroup_15878_Name = {
    Text = "Dây xích đen tối"
  },
  StageGroup_15878_StageGroupRewardDescription = {
    Text = "<Black:nguyên liệu kỹ năng nâng cao>"
  },
  StageGroup_15878_TypeText = {
    Text = "Dây xích đen tối"
  },
  StageGroup_15879_Desc = {
    Text = "\"Bàn Tay\" vén lên bức màn của đêm đen, lặng lẽ tiến vào thế giới này."
  },
  StageGroup_15879_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15879_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15880_Desc = {
    Text = "\"Bàn Tay\" vén lên bức màn của đêm đen, lặng lẽ tiến vào thế giới này."
  },
  StageGroup_15880_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15880_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15881_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
  StageGroup_15881_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15881_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15882_Desc = {
    Text = "Trái ngược với định kiến về \"hysteria\", đây là một thế giới tĩnh lặng và không tiếng động."
  },
  StageGroup_15882_Name = {
    Text = "Nơi im lặng sâu thẳm"
  },
  StageGroup_15882_TypeText = {
    Text = "Điều tra"
  },
  StageGroup_15883_Desc = {
    Text = "\nĐã từng có một trường đại học tồn tại, nỗ lực đem đến tia hi vọng mong manh cùng dũng khí cho loài người \nVề phần kết cục của nó, hiện tại chúng ta đang được chứng kiến - bị chôn vùi trong vụn vỡ và hoang tàn."
  },
  StageGroup_15883_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15883_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15884_Desc = {
    Text = "Chúng vặn vẹo, hòa quyện trong bóng tối, rồi được cẩn thận bảo quản trong tượng. \nĐây là một cuộc hội ngộ đã được dự mưu từ lâu."
  },
  StageGroup_15884_Name = {
    Text = "Hành trình Siêu việt"
  },
  StageGroup_15884_TypeText = {
    Text = "Hành trình Siêu việt"
  },
  StageGroup_15885_Desc = {
    Text = "\"Mỗi chìa khóa đều có một con số độc nhất, và cũng chỉ thuộc về một điều tra viên duy nhất.\" \n\"Điều đó cũng đồng nghĩa rằng, thời khắc chìa khóa rơi xuống cũng đánh dấu cái chết của điều tra viên sở hữu nó.\" \n\"Điều này tuyệt vời làm sao, vì ngay cả cái chết cũng là độc nhất vô nhị.\""
  },
  StageGroup_15885_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15885_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15886_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  StageGroup_15886_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15886_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15887_Desc = {
    Text = "Dâng lên thực tại tạo nên từ thịt và máu, chúng là hố sâu không bao giờ no đủ."
  },
  StageGroup_15887_Name = {
    Text = "Residu hữu cơ"
  },
  StageGroup_15887_StageGroupRewardDescription = {
    Text = "<Black:vật liệu thăng cấp>"
  },
  StageGroup_15887_TypeText = {
    Text = "Residu hữu cơ"
  },
  StageGroup_15888_Desc = {
    Text = "Theo các ghi chép chính thức, tổng cộng hơn ba nghìn người đã tham gia vào Cuộc Thập tự chinh Thần thánh thứ @1. \n Mục tiêu của các thánh đồ không giống nhau, có người vì sinh kế, có người vì báo thù. \n Còn có người vì thú vui giết chóc."
  },
  StageGroup_15888_Name = {
    Text = "Máu và cát"
  },
  StageGroup_15888_TypeText = {
    Text = "duy thức tiềm hành"
  },
  StageGroup_15889_Desc = {
    Text = "Đây là một màn chơi thử nghiệm"
  },
  StageGroup_15889_Name = {
    Text = "Cấp độ thử nghiệm"
  },
  StageGroup_15889_TypeText = {
    Text = "Điều tra"
  },
  StageGroup_15890_Desc = {
    Text = "Những ngôi sao rơi vào biển sâu, dưới đáy biển lấp lánh những ước nguyện không ai hiểu được."
  },
  StageGroup_15890_Name = {
    Text = "Ngôi sao xoắn"
  },
  StageGroup_15890_TypeText = {
    Text = "Điều tra"
  },
  StageGroup_15891_Desc = {
    Text = "Đây là nơi ngủ say của một thành phố cổ xưa. \nNó thích ngủ như chủ nhân của nó."
  },
  StageGroup_15891_Name = {
    Text = "Phế tích của Ponape"
  },
  StageGroup_15891_StageGroupRewardDescription = {
    Text = "<Black:kỹ năng nguyên liệu>"
  },
  StageGroup_15891_TypeText = {
    Text = "Phế tích của Ponape"
  },
  StageGroup_15892_Desc = {
    Text = "Chúng vốn là tập hợp vô thức của nỗi buồn, sự méo mó và bối rối, \n nhưng lại được ngụy trang thành những đứa trẻ, người lớn và thú cưng hạnh phúc. \n Vì chưa bao giờ biết đến hạnh phúc, chúng trở thành những diễn viên tồi tệ nhất."
  },
  StageGroup_15892_Name = {
    Text = "Bí mật tượng nến"
  },
  StageGroup_15892_StageGroupRewardDescription = {
    Text = "<Black:nguyên liệu kỹ năng nâng cao>"
  },
  StageGroup_15892_TypeText = {
    Text = "Bí mật tượng nến"
  },
  StageGroup_15893_Desc = {
    Text = "Quốc độ của Ngài là xác thân của vũ trụ, ham muốn của Ngài không giới hạn."
  },
  StageGroup_15893_Name = {
    Text = "Sarang Cacing"
  },
  StageGroup_15893_StageGroupRewardDescription = {
    Text = "<Black:kỹ năng nguyên liệu>"
  },
  StageGroup_15893_TypeText = {
    Text = "Sarang Cacing"
  },
  StageGroup_15894_Desc = {
    Text = "Mỗi đêm mưa rơi đều đi kèm với ý định giết người. \nLần này bạn sẽ đến thị trấn Renni phía bắc của thị trấn Rai, để điều tra một vụ án kỳ lạ…"
  },
  StageGroup_15894_Name = {
    Text = "Bóng tối của thị trấn mưa"
  },
  StageGroup_15894_TypeText = {
    Text = "Bản ghi đặc nhiệm"
  },
  StageGroup_15895_Desc = {
    Text = "Một bảo tàng sáp có thể tham quan miễn phí. \nNó chỉ mở cánh cửa tối om của mình vào nửa đêm, chào đón những kẻ đến với ý đồ xấu…"
  },
  StageGroup_15895_Name = {
