  StageGroup_15896_TypeText = {
    Text = "Điều tra Điên loạn"
  },
  StageGroup_15897_Desc = {
    Text = "Cô ấy đã dùng thân mình để chứa đựng thánh cốt, dùng giáo lý để hướng dẫn tín đồ, dùng nọc độc để truyền bá đức tin. \nLời cầu nguyện và lời kêu gọi của cô ấy vang vọng mãi không ngừng."
  },
