  StageGroup_15905_Desc = {
    Text = "Chiếc thuyền lạ, cô gái lạ, kẻ thù lạ. Trôi dạt giữa biển khơi, điều chờ đợi các điều tra viên là một cuộc đấu tranh với số phận…"
