  StageGroup_15920_TypeText = {
    Text = "Điều tra Điên loạn"
  },
  StageGroup_15921_Desc = {
    Text = "Trái ngược với định kiến về \"hysteria\", đây là một thế giới tĩnh lặng và không tiếng động."
  },
  StageGroup_15921_Name = {
    Text = "Nơi im lặng sâu thẳm"
  },
  StageGroup_15921_TypeText = {
    Text = "Điều tra Khó khăn"
  },
  StageGroup_15922_Desc = {
    Text = "Chào mừng đến với thị trấn Rai hiếu khách —— tiếng sủa của chó trong đêm đông sẽ khiến mỗi du khách cảm thấy như ở nhà."
  },
  StageGroup_15922_Name = {
    Text = "Cẩn thận với chó"
  },
  StageGroup_15922_TypeText = {
    Text = "Điều tra"
  },
  StageGroup_15923_Desc = {
    Text = "Theo các ghi chép chính thức, tổng cộng hơn ba nghìn người đã tham gia vào Cuộc Thập tự chinh Thần thánh thứ @1. \n Mục tiêu của các thánh đồ không giống nhau, có người vì sinh kế, có người vì báo thù. \n Còn có người vì thú vui giết chóc."
  },
  StageGroup_15923_Name = {
    Text = "Máu và cát"
  },
  StageGroup_15923_TypeText = {
    Text = "duy thức tiềm hành"
  },
  StageGroup_15924_Desc = {
    Text = "Elworth nằm ở cực điểm của cà đa sác, quanh năm bị phủ bởi tuyết băng không tan, \ndưới lớp băng dày và cứng cáp, ẩn chứa những nhịp đập của sức sống."
  },
  StageGroup_15924_Name = {
    Text = "Dãy núi Hỗn loạn"
  },
  StageGroup_15924_StageGroupRewardDescription = {
