  StageGroup_15926_Name = {
    Text = "Màn chơi thử nghiệm nhân vật"
  },
  StageGroup_15926_TypeText = {
    Text = "Cấp độ sự kiệ"
  },
  StageGroup_15927_Desc = {
    Text = "Sương mù đêm cổ xưa bao trùm Lentiennam. Trong những góc tối mà ánh đèn đường mờ không thể chiếu sáng, bóng tối đang rình rập."
  },
  StageGroup_15927_Name = {
    Text = "Bí mật đông"
  },
  StageGroup_15927_TypeText = {
    Text = "Điều tra"
  },
  StageGroup_15928_Desc = {
    Text = "Những đứa trẻ không được ban phước ngâm bài thánh ca trong biển. \n Xì… Xin hãy giữ im lặng, đừng làm phiền giấc ngủ dài của Ngài."
  },
  StageGroup_15928_Name = {
    Text = "Cáo ca của Thánh thai"
  },
  StageGroup_15928_StageGroupRewardDescription = {
    Text = "<Black:nguyên liệu kỹ năng nâng cao>"
  },
  StageGroup_15928_TypeText = {
    Text = "Cáo ca của Thánh thai"
  },
  StageGroup_15929_Desc = {
    Text = "Chúng vặn vẹo, hòa quyện trong bóng tối, rồi được cẩn thận bảo quản trong tượng. \nĐây là một cuộc hội ngộ đã được dự mưu từ lâu."
  },
  StageGroup_15929_Name = {
    Text = "Đầm lầy thịt máu"
  },
  StageGroup_15929_TypeText = {
    Text = "Đầm lầy thịt máu"
  },
  StageGroup_15930_Desc = {
    Text = "Chúng vặn vẹo, hòa quyện trong bóng tối, rồi được cẩn thận bảo quản trong tượng. \nĐây là một cuộc hội ngộ đã được dự mưu từ lâu."
  },
  StageGroup_15930_Name = {
    Text = "Đầm lầy thịt máu"
  },
  StageGroup_15930_TypeText = {
    Text = "Đầm lầy thịt máu"
  },
  StageGroup_15931_Desc = {
    Text = "Chúng vặn vẹo, hòa quyện trong bóng tối, rồi được cẩn thận bảo quản trong tượng. \nĐây là một cuộc hội ngộ đã được dự mưu từ lâu."
  },
  StageGroup_15931_Name = {
    Text = "Đầm lầy thịt máu"
  },
  StageGroup_15931_TypeText = {
    Text = "Đầm lầy thịt máu"
  },
  StageGroup_15932_Desc = {
    Text = "Vương quốc Leo có Biển Bắc hiền hòa và yên bình vào mùa hè giữa năm. \nMùa đông nơi đây trông cũng thanh lịch và tao nhã, nhưng dưới những đám mây sáng rực tĩnh lặng và hoa lệ, thường ẩn chứa những cơn bão chết người."
  },
  StageGroup_15932_Name = {
    Text = "Biển Bão Ngoài"
  },
  StageGroup_15932_StageGroupRewardDescription = {
    Text = "<Black:bí ẩn>"
  },
  StageGroup_15932_TypeText = {
    Text = "Biển Bão Ngoài"
  },
  StageGroup_15933_Desc = {
    Text = "Tất cả cấp độ thân thể được đánh thức, cấp độ kỹ năng, cường độ vật phẩm điều chỉnh về cấp 1. \nTự do chọn lựa kết hợp cảm ứng cửa ải, kết hợp cảm ứng sao càng cao, phần thưởng nhận được sau khi hoàn thành càng nhiều."
  },
  StageGroup_15933_Name = {
    Text = "Lao xuống huyễn tưởng"
  },
  StageGroup_15933_TypeText = {
    Text = "Lao xuống huyễn tưởng"
  },
  StageGroup_15934_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
  StageGroup_15934_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15934_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15935_Desc = {
    Text = "Ngày khởi hành, mưa nhẹ rơi nơi Huyệt Nghĩa. Chôn cất bia mộ, tên và lời thề của bạn ở đây."
  },
  StageGroup_15935_Name = {
    Text = "Ngày nhập học"
  },
  StageGroup_15935_TypeText = {
    Text = "Điều tra"
  },
  StageGroup_15936_Desc = {
    Text = "Trước khi các ngôi sao được sinh ra, chúng đã tồn tại ở đây. \nChúng vừa là hư vô, vừa là tất cả."
  },
  StageGroup_15936_Name = {
    Text = "Dư ảnh đục"
  },
  StageGroup_15936_StageGroupRewardDescription = {
    Text = "<Black:vật liệu thăng cấp>"
  },
  StageGroup_15936_TypeText = {
    Text = "Dư ảnh đục"
  },
  StageGroup_15937_Desc = {
    Text = "\nĐã từng có một trường đại học tồn tại, nỗ lực đem đến tia hi vọng mong manh cùng dũng khí cho loài người \nVề phần kết cục của nó, hiện tại chúng ta đang được chứng kiến - bị chôn vùi trong vụn vỡ và hoang tàn."
  },
  StageGroup_15937_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15937_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15938_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  StageGroup_15938_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15938_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15939_Desc = {
    Text = "\"Mỗi chìa khóa đều có một con số độc nhất, và cũng chỉ thuộc về một điều tra viên duy nhất.\" \n\"Điều đó cũng đồng nghĩa rằng, thời khắc chìa khóa rơi xuống cũng đánh dấu cái chết của điều tra viên sở hữu nó.\" \n\"Điều này tuyệt vời làm sao, vì ngay cả cái chết cũng là độc nhất vô nhị.\""
  },
  StageGroup_15939_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15939_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15940_Desc = {
    Text = "Bước đầu tiên để trở thành một nhà dược tài ba."
  },
  StageGroup_15940_Name = {
    Text = "Chế phẩm luyện kim"
  },
  StageGroup_15940_StageGroupRewardDescription = {
    Text = "<Black:thuốc linh tri>"
  },
  StageGroup_15940_TypeText = {
    Text = "Chế phẩm luyện kim"
  },
  StageGroup_15941_Desc = {
    Text = "\"Bàn Tay\" vén lên bức màn của đêm đen, lặng lẽ tiến vào thế giới này."
  },
  StageGroup_15941_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15941_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_15942_Desc = {
    Text = "Thị trấn Rai nằm ở phía đông bắc của Lentiennam, ẩn sâu trong dãy núi liên tục. \n Người dân im lặng, ánh mắt theo dõi khắp nơi… Hãy cẩn thận, mọi thứ ở đây đều không bình thường."
  },
  StageGroup_15942_Name = {
