    Text = "Cuộc sống có liên quan hoặc không liên quan đến sự bí ẩn, đều không thể thiếu quyền vàng hồng. \nTrong những phế tích bị ăn mòn mà người thường không thể cư ngụ, có thể ẩn chứa những bảo vật vô cùng quý giá."
