  StageGroup_20222_Desc = {
    Text = "Thiếu nữ Camille được đưa đến trước mặt tiểu thư Sơn khi mới năm tuổi. \n Sơn đẹp như một bức điêu khắc, vừa gần gũi vừa xa cách. Cô ấy mỉm cười với Camille dưới ánh nắng mặt trời. \n Từ ngày đó, Camille ước nguyện: Chúng ta sẽ mãi mãi bên nhau."
