  StageGroup_20446_Desc = {
    Text = "Theo truyền thuyết, dưới lòng đất của Lentiennam, có một cánh cửa duy nhất. \n Nó dẫn đến nơi ở của Chủ Tể Bạc Nhợt…"
  },
  StageGroup_20446_Name = {
    Text = "Hậu duệ người da trắng"
  },
  StageGroup_20446_TypeText = {
    Text = "duy thức tiềm hành"
  },
  StageGroup_20447_Desc = {
    Text = "Cô ấy là một con rối được phục hồi bởi Đại học Misag. \n Bộ xương của cô ấy là kim loại, trái tim của cô ấy là bạc tâm, cấu trúc của cô ấy vô cùng tinh vi, ngay cả khi đối diện với bản vẽ thiết kế, cũng khó có thể tạo ra một cái thứ hai. \n Và trước khi trở thành một cỗ máy lạnh giá, cô ấy đã có một trái tim của con người."
  },
  StageGroup_20447_Name = {
    Text = "Lõi xoắn"
  },
  StageGroup_20447_TypeText = {
    Text = "duy thức tiềm hành"
  },
