  StageGroup_51755_Desc = {
    Text = "Một đại dương đã chết, cô chôn cất xác của biển cả. \n Trên phản chiếu của biển sâu, giấc mơ của vua tan biến, vương quốc của thần đã thối rữa. \n Cô thấy mình từ những ảo mộng xưa cũ bước ra, bước vào đống đổ nát tương lai sụp đổ. \n Cô hỏi hố sâu, hố sâu im lặng không trả lời. \n Cô tế lễ cho hố sâu, đáp lại cô chỉ có chính bản thân cô."
  },
