  StageGroup_55453_Desc = {
    Text = "Tất cả những chữ viết đều hóa thành tro tàn, tất cả những cánh hoa đều rụng xuống thành bùn. \nHít thở dư hương của khu vườn, hãy để tôi dâng tặng bạn một bài thơ nữa. \nTrong trái tim hoang vắng của con người, đóa hồng vẫn đỏ thắm."
