  StageGroup_56440_Desc = {
    Text = "Người giữ bí mật vô tình bước vào cuộc đấu trí do \"Ngài\" bày ra. \nMặt trăng đỏ, ngôi nhà cổ, cơn bão tuyết và những người tham gia với mục đích riêng... \nCuộc đấu trí giữa tâm hồn và lý trí, ngay lập tức khai màn."
  },
  StageGroup_56440_Name = {
    Text = "Chúc săn bắn vui vẻ!"
