  },
  StageGroup_56443_Desc = {
    Text = "Tuyết lớn chôn vùi hơi thở tĩnh lặng của dãy núi và số phận mà những người trở về lần lượt theo đuổi. \n Elworth, nơi lạnh giá quanh năm, chiến binh đã giơ cao thanh kiếm trong tay. \n Cô sẽ chiến đấu vì mùa xuân đầu tiên trong sức sống của mình."
