    Text = "Vào sân. Ngồi yên lặng. Chờ đợi. Khát khao. \nCây đũa chỉ huy nhẹ nhàng nâng lên. Bạn đã sẵn sàng để lắng nghe những bí ẩn sâu thẳm nhất của vũ trụ chưa?"
