  StageGroup_67785_Desc = {
    Text = "Ngài đã có một giấc mơ dài. \nNgài mơ thấy thần và các vì sao, mơ thấy bụi hóa thành văn minh, văn minh hóa thành bụi. \nNgài mơ thấy hận và yêu, mơ thấy vui sướng và sợ hãi. \nNgài tỉnh dậy từ giấc mơ. Mọi thứ trong giấc mơ, chưa bao giờ tồn tại."
