  },
  StageGroup_70938_Desc = {
    Text = "Viện điều dưỡng được xây dựng từ tiềm thức của tập thể\nTại đây, sự phân hủy của thân xác không phải là điểm kết thúc, mà cái chết của tâm hồn mới là kết thúc.\nHỡi những người bước vào, hãy giữ vững lý trí, nhân tính là điều duy nhất bạn dựa vào khi băng qua mê cung tâm hồn."
  },
  StageGroup_70938_Name = {
    Text = "Biến thân"
  },
  StageGroup_70938_TypeText = {
    Text = "Điều tra"
  },
  StageGroup_70939_Desc = {
    Text = "Thành phố phế tích bị chôn vùi trong sương xám\nvượt qua những vì tinh tú tối tăm, tái ngộ với những mảnh vỡ của ý chí vô thượng trong chiều hư hỏng"
  },
  StageGroup_70939_Name = {
    Text = "Trở lại thành phố sương mù"
  },
  StageGroup_70939_TypeText = {
    Text = "Điều tra"
  },
  StageGroup_70940_Desc = {
    Text = "Hãy tổ chức một buổi lễ, bạn của tôi ♪\nXương cốt dưới ánh trăng khẽ khẽ nở rộ, một người yêu dấu được đưa lên đĩa tiệc ♪\nTất cả khách mời đã đến! Hát nào, nhảy nào ♪\nChúng tôi không bao giờ cầu nguyện cho linh hồn, chúng tôi không bao giờ thương tiếc cho xác chết ♪\nCô ấy đã giao ký ức cho tôi, cô ấy đã giao nước mắt cho tôi ♪\nHãy để chúng ta nuốt linh hồn và thịt thối của cô ấy ♪\nTrong bữa tiệc của cái chết, chúng ta sẽ đoàn tụ một lần nữa ♪"
  },
  StageGroup_70940_Name = {Text = "Tham ăn"},
  StageGroup_70940_TypeText = {
    Text = "Điều tra"
  },
  StageGroup_71850_Desc = {
    Text = "Sự vinh quang, sự kính trọng, quyền lực vô hạn, ngai vàng tối cao vô thượng. \n Điều cần thiết để lên ngai vàng chỉ là được thần chọn. \n Vậy, tất cả những điều này sẽ phải trả giá như thế nào?"
  },
  StageGroup_71850_Name = {
    Text = "Ngày Đăng Quang"
  },
  StageGroup_71850_TypeText = {
    Text = "duy thức tiềm hành"
  },
  StageGroup_72073_Desc = {
    Text = "Hãy tổ chức một buổi lễ, bạn của tôi ♪\nXương cốt dưới ánh trăng khẽ khẽ nở rộ, một người yêu dấu được đưa lên đĩa tiệc ♪\nTất cả khách mời đã đến! Hát nào, nhảy nào ♪\nChúng tôi không bao giờ cầu nguyện cho linh hồn, chúng tôi không bao giờ thương tiếc cho xác chết ♪\nCô ấy đã giao ký ức cho tôi, cô ấy đã giao nước mắt cho tôi ♪\nHãy để chúng ta nuốt linh hồn và thịt thối của cô ấy ♪\nTrong bữa tiệc của cái chết, chúng ta sẽ đoàn tụ một lần nữa ♪"
  },
  StageGroup_72073_Name = {Text = "Tham ăn"},
  StageGroup_72073_TypeText = {
    Text = "Điều tra Khó khăn"
  },
  StageGroup_72074_Desc = {
    Text = "Viện điều dưỡng được xây dựng từ tiềm thức của tập thể\nTại đây, sự phân hủy của thân xác không phải là điểm kết thúc, mà cái chết của tâm hồn mới là kết thúc.\nHỡi những người bước vào, hãy giữ vững lý trí, nhân tính là điều duy nhất bạn dựa vào khi băng qua mê cung tâm hồn."
  },
  StageGroup_72074_Name = {
    Text = "Biến thân"
  },
  StageGroup_72074_TypeText = {
    Text = "Điều tra Khó khăn"
  },
  StageGroup_72075_Desc = {
    Text = "Thành phố phế tích bị chôn vùi trong sương xám\nvượt qua những vì tinh tú tối tăm, tái ngộ với những mảnh vỡ của ý chí vô thượng trong chiều hư hỏng"
  },
  StageGroup_72075_Name = {
    Text = "Trở lại thành phố sương mù"
  },
  StageGroup_72075_TypeText = {
    Text = "Điều tra Khó khăn"
  },
  StageGroup_74236_Desc = {
    Text = "Đêm lửa cháy ngập trời, không chỉ có nghệ thuật của cô ấy được hồi sinh."
  },
  StageGroup_74236_Name = {
    Text = "Đam mê hóa thành cát bụi"
  },
  StageGroup_74236_TypeText = {
    Text = "duy thức tiềm hành"
  },
  StageGroup_74237_Desc = {
    Text = "Đêm lửa cháy ngập trời, không chỉ có nghệ thuật của cô ấy được hồi sinh."
  },
  StageGroup_74237_Name = {
    Text = "Đam mê hóa thành cát bụi"
  },
  StageGroup_74237_TypeText = {
    Text = "duy thức tiềm hành"
  },
  StageGroup_74238_Desc = {
    Text = "Đêm lửa cháy ngập trời, không chỉ có nghệ thuật của cô ấy được hồi sinh."
  },
  StageGroup_74238_Name = {
    Text = "Đam mê hóa thành cát bụi"
  },
  StageGroup_74238_TypeText = {
    Text = "duy thức tiềm hành"
  },
  StageGroup_74338_Desc = {
    Text = "Cuộc đối đầu pha đã chào đón sự xuất hiện của một tồn tại bí ẩn, cô gái với đôi sừng trên đầu đã đưa ra lời thách đấu đến mọi người. \n Thu thập hạt dẻ, đánh bại kẻ thù mạnh mẽ, tất cả đều vì mục đích đảo ngược không gian một lần nữa. \n Khi ánh bạc lóe lên xuyên qua bầu trời và phá vỡ mặt trời rực rỡ chiếu sáng muôn nơi, cô gái mới bỗng nhiên hiểu ra. \n Hóa ra điều mà cô ấy luôn không thể buông bỏ chính là sự chấp niệm từ quá khứ. \n Xiềng xích đã bị phá vỡ, chấp niệm đã được xóa bỏ, cô gái kết thúc chuyến hành trình và gửi tặng những lời chúc chân thành nhất đến bạn bè."
  },
  StageGroup_74338_Name = {
    Text = "Đảo ngược lượt"
  },
  StageGroup_74338_TypeText = {
    Text = "Kết nối đa chiều"
  },
  StageGroup_75263_Desc = {
    Text = "\nĐã từng có một trường đại học tồn tại, nỗ lực đem đến tia hi vọng mong manh cùng dũng khí cho loài người \nVề phần kết cục của nó, hiện tại chúng ta đang được chứng kiến - bị chôn vùi trong vụn vỡ và hoang tàn."
  },
  StageGroup_75263_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_75263_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_75264_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  StageGroup_75264_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_75264_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_75265_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
  StageGroup_75265_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_75265_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_75266_Desc = {
    Text = "\"Bàn Tay\" vén lên bức màn của đêm đen, lặng lẽ tiến vào thế giới này."
  },
  StageGroup_75266_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_75266_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_75267_Desc = {
    Text = "\"Bàn Tay\" vén lên bức màn của đêm đen, lặng lẽ tiến vào thế giới này."
  },
  StageGroup_75267_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_75267_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_75268_Desc = {
    Text = "\nĐã từng có một trường đại học tồn tại, nỗ lực đem đến tia hi vọng mong manh cùng dũng khí cho loài người \nVề phần kết cục của nó, hiện tại chúng ta đang được chứng kiến - bị chôn vùi trong vụn vỡ và hoang tàn."
  },
  StageGroup_75268_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_75268_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_75269_Desc = {
    Text = "\"Mỗi chìa khóa đều có một con số độc nhất, và cũng chỉ thuộc về một điều tra viên duy nhất.\" \n\"Điều đó cũng đồng nghĩa rằng, thời khắc chìa khóa rơi xuống cũng đánh dấu cái chết của điều tra viên sở hữu nó.\" \n\"Điều này tuyệt vời làm sao, vì ngay cả cái chết cũng là độc nhất vô nhị.\""
  },
  StageGroup_75269_Name = {
    Text = "Thâm Nhập Mộng Ảo"
  },
  StageGroup_75269_TypeText = {
    Text = "Thâm Nhập Mộng Ảo"
  },
