  },
  StageGroup_81262_Desc = {
    Text = "Đáng lẽ đây phải là một cuộc hành trình tràn đầy tiếng cười và tiếng hát.\nChiếc du thuyền sang trọng, tuần tra Đại Tây Dương, chở theo chiến lợi phẩm, mang theo khát vọng chinh phục đại dương của con người.\nNhưng đại dương có tâm trạng riêng của nó.\nTrước nỗi sợ hãi và điều chưa biết vượt quá sự hiểu biết, con người, cuối cùng vẫn nhỏ bé như côn trùng."
  },
