  },
  StageGroup_88934_Desc = {
    Text = "Đây là một bài ca chim hót về bầu trời.\nThế giới bên ngoài rốt cuộc như thế nào?\nCó những hiệp sĩ trung thành và những công chúa xinh đẹp, có những cánh đồng bao la và những chú ngựa dũng mãnh không?\nHãy đi đi, hãy đi xem, hôm nay chuẩn bị lên đường nhé.\nGặm đứt xích chân và hàng rào, bay về phía bầu trời sao và mặt trăng.\nĐừng sợ bị thương và đói.\nCái kết thúc của con đường tự do, chắc chắn sẽ tràn đầy suối nguồn và hoa tươi."
  },
